Context()->flags->set(tolType => 'absolute', tolerance => 3, limits => [0,6]); $f = Formula("12.8*x + 91.38"); Context()->operators->set( '+'=>{class => 'bizarro::BOP::add', isCommand => 1}, '-'=>{class => 'bizarro::BOP::subtract', isCommand => 1}, ); parser::Assignment->Allow; Context()->variables->add(y => 'Real'); $eq = Formula("y = $f"); $ev = $eq->cmp()->withPostFilter( sub{ my $ans = shift; $ans->{ans_message} = "An equation for a line in slope-intercept form should start with 'y='" if $ans->{ans_message} eq "The left side of an assignment must be a variable or function"; return $ans; } );
$image_1 = createLaTeXImage(); $image_1->addToPreamble(latexImagePreamble()); $image_1->BEGIN_LATEX_IMAGE \begin{tikzpicture} \begin{axis}[ xmin=0, xmax=6, ymin=0, ymax=200, ytick=, minor ytick={10,20,...,200}, xlabel = {pressure (bara)}, ylabel = {temperature (Celsius)}, width=0.47\orccaprintwidth, axis line style={->}, ] \addplot+[-{Kite}, domain=0:6] {12.8*x + 91.38}; \addplot[soliddot] coordinates {(1,99.6) (2,120.2) (3,133.6) (4,143.6) (5,151.9)}; \end{axis} \end{tikzpicture}
